class VersionedArray {
  private ids: number[][];
  private vals: number[][];
  private current = 0;

  constructor(length: number) {
    this.ids = Array.from({ length }, () => []);
    this.vals = Array.from({ length }, () => []);
  }

  set(index: number, val: number): void {
    const ids = this.ids[index], vals = this.vals[index];
    if (ids.length && ids[ids.length - 1] === this.current) vals[vals.length - 1] = val;
    else { ids.push(this.current); vals.push(val); }
  }

  snap(): number { return this.current++; }

  get(index: number, snapId: number): number {
    const ids = this.ids[index];
    // find the first id greater than snapId; the entry before it is the answer
    let lo = 0, hi = ids.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ids[mid] <= snapId) lo = mid + 1;
      else hi = mid;
    }
    return lo === 0 ? 0 : this.vals[index][lo - 1];
  }
}

